package cn.zhuatech.iam.deep;import cn.zhuatech.iam.common.ApiResponse;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/iam-ops")public class DeepDomainController{private final DeepDomainService s;public DeepDomainController(DeepDomainService s){this.s=s;}@GetMapping("/dashboard")ApiResponse<?>dashboard(@RequestParam String tenantCode){return ApiResponse.ok(s.dashboard(tenantCode));}@PostMapping("/tenants/{id}/identities")ApiResponse<?>identity(@PathVariable Long id,@Valid@RequestBody DeepDomainService.IdentityRequest r){return ApiResponse.ok(s.identity(id,r));}@PostMapping("/access-requests")ApiResponse<?>request(@Valid@RequestBody DeepDomainService.AccessRequestInput r){return ApiResponse.ok(s.request(r));}}
